import{_ as e,o as a,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"核心知识总览","description":"","frontmatter":{"title":"核心知识总览"},"headers":[],"relativePath":"frontend/guide/core/index.md","filePath":"frontend/guide/core/index.md","lastUpdated":1785666337000}'),d={name:"frontend/guide/core/index.md"};function s(i,t,o,l,p,c){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="核心知识总览" tabindex="-1">核心知识总览 <a class="header-anchor" href="#核心知识总览" aria-label="Permalink to &quot;核心知识总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>核心知识建立前端工程师共享的技术底座。这里关注 Web 平台提供什么能力、语言语义如何影响程序、框架如何组织 UI，以及真实 Web 应用由哪些通用问题组成。</p><p>本模块既提供可查询的 API 参考，也建立理解 API 所需的原理和心智模型。学习一项知识时，应能够说明它解决的问题、运行边界、常见失败方式，以及它与上下游系统的关系。</p><h2 id="知识结构" tabindex="-1">知识结构 <a class="header-anchor" href="#知识结构" aria-label="Permalink to &quot;知识结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>核心问题</th><th>学习结果</th></tr></thead><tbody><tr><td><a href="/frontend/guide/core/web/html/">HTML</a> 与 <a href="/frontend/guide/core/web/css/selectors-states">CSS</a></td><td>页面如何获得语义、布局、视觉和适配能力</td><td>能构建结构可靠、可访问、可维护的界面</td></tr><tr><td><a href="/frontend/guide/core/javascript/">JavaScript 语言</a></td><td>语言语义和运行时行为如何影响程序</td><td>能处理语法、类型、作用域、异步、模块、内存和错误</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library">JavaScript 标准库</a></td><td>标准内置对象和方法分别解决什么问题</td><td>能查询并正确选择集合、文本、数值、时间和异步 API</td></tr><tr><td><a href="/frontend/guide/core/typescript/">TypeScript</a></td><td>如何用类型表达约束并守住系统边界</td><td>能设计稳定的类型、类、公共 API 和工程配置</td></tr><tr><td><a href="/frontend/guide/core/web/apis/dom">DOM 与 Web API</a></td><td>浏览器向应用暴露了哪些平台能力</td><td>能使用 DOM、事件、网络、存储、Worker、Crypto 和设备 API</td></tr><tr><td><a href="/frontend/guide/core/web/browser/architecture">浏览器</a></td><td>代码如何在浏览器中加载、执行和渲染</td><td>能解释进程、渲染、事件循环、缓存和调试机制</td></tr><tr><td><a href="/frontend/guide/core/web/network/foundations">网络</a></td><td>请求如何跨越浏览器、网络和服务端</td><td>能分析协议、缓存、安全与实时通信问题</td></tr><tr><td><a href="/frontend/guide/core/frameworks/ecosystem-landscape">框架通用</a></td><td>不同 UI 框架共享哪些模型，又有哪些差异</td><td>能从组件、状态、渲染和 Hydration 理解框架</td></tr><tr><td><a href="/frontend/guide/core/react/">React 19</a></td><td>React 最新主版本如何组织组件与全栈应用</td><td>能正确使用 Hooks、并发能力、Actions 和 RSC 生态</td></tr><tr><td><a href="/frontend/guide/core/vue/">Vue 3</a></td><td>Vue 3 最新 API 如何组织响应式应用</td><td>能正确使用 Composition API、生态工具和 Nuxt</td></tr><tr><td><a href="/frontend/guide/core/application/routing-navigation">Web 应用通用能力</a></td><td>业务应用反复遇到的问题如何建模</td><td>能处理路由、状态、请求、表单、权限和异常状态</td></tr></tbody></table><h2 id="推荐学习顺序" tabindex="-1">推荐学习顺序 <a class="header-anchor" href="#推荐学习顺序" aria-label="Permalink to &quot;推荐学习顺序&quot;">​</a></h2><p>基础主线按照依赖关系推进：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTML 与 CSS</span></span>
<span class="line"><span>    -&gt; JavaScript 语言与标准库</span></span>
<span class="line"><span>    -&gt; TypeScript</span></span>
<span class="line"><span>    -&gt; DOM 与 Web API、浏览器、网络</span></span>
<span class="line"><span>    -&gt; 框架通用</span></span>
<span class="line"><span>    -&gt; React 19 或 Vue 3</span></span>
<span class="line"><span>    -&gt; Web 应用通用能力</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>React 和 Vue 不需要同时作为入门前置。先选择一个作为主技术栈，达到能够独立设计和交付应用的程度，再通过框架通用模型学习另一套框架，效率更高。</p><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li>核心知识解释技术是什么、如何使用以及能力边界。</li><li><a href="/frontend/guide/engineering/">工程体系</a>解释如何让应用可构建、可测试、可发布、可观测和可演进。</li><li><a href="/frontend/topics/">专题进阶</a>系统展开算法、设计模式、可视化、跨端和 AI 等独立技术领域。</li><li><a href="/frontend/deep-dive/">原理深挖</a>解释框架、浏览器和工具链内部如何实现。</li><li><a href="/frontend/decisions/">技术决策</a>比较多个可行方案在具体约束下的取舍。</li><li><a href="/frontend/practices/">项目实战</a>把多个知识域组合成可交付的完整系统。</li></ul><h2 id="掌握标准" tabindex="-1">掌握标准 <a class="header-anchor" href="#掌握标准" aria-label="Permalink to &quot;掌握标准&quot;">​</a></h2><p>完成本模块不等于读完所有页面。更可靠的判断标准是：</p><ul><li>能从浏览器、网络和语言层解释常见故障，而不是只尝试更换框架 API。</li><li>能区分 ECMAScript 标准库、Web API、Node.js API 和第三方库。</li><li>能区分客户端状态、服务端状态、URL 状态和持久化状态。</li><li>能说明 React 与 Vue 在组件、响应式和渲染策略上的共同点与差异。</li><li>能在类型系统、运行时校验和外部数据之间建立明确边界。</li><li>能为技术选择给出原理和约束，而不是只引用流行度或个人偏好。</li></ul>`,15)])])}const b=e(d,[["render",s]]);export{u as __pageData,b as default};
